#!/usr/bin/env bash
# Run staged ACT4 ELFs (third_party/ara/act-elfs/, generated by
# scripts/build_act4_cva6v.sh) on the verilated CVA6+Ara model.
# Run inside the Ara container:
#   ./scripts/ara_docker.sh /repo/sw/act4-cva6v/run_actv.sh [first] [last]
# Optional args: first and last index (1-based) into the sorted ELF list.
# Emits one CSV line per test: name,PASS|FAIL|TIMEOUT,cycles
# Verdict logic follows upstream run-ara.sh: the testbench exits 0 on
# its cycle limit and the halt exit code is (stored value >> 1), so
# the RVCP-SUMMARY console lines decide pass/fail.
set -uo pipefail
SIM=/repo/third_party/ara/hardware/build/verilator/Vara_tb_verilator
ELFS_DIR=/repo/third_party/ara/act-elfs
CYCLES="${ARA_CYCLES:-20000000}"
FIRST="${1:-1}"; LAST="${2:-999999}"
i=0
for elf in $(ls "$ELFS_DIR" | sort); do
  i=$((i+1))
  [ "$i" -lt "$FIRST" ] && continue
  [ "$i" -gt "$LAST" ] && break
  rundir="$(mktemp -d)"
  ( cd "$rundir" && timeout 600 "$SIM" -c "$CYCLES" \
      -l "ram,$ELFS_DIR/$elf,elf" > sim.log 2>&1 )
  rc=$?
  cyc=$(grep -a "Executed cycles" "$rundir/sim.log" | awk '{print $3}')
  if [ "$rc" -eq 124 ] || grep -aq 'Simulation timeout of' "$rundir/sim.log"; then
    echo "$elf,TIMEOUT,$cyc"
  elif grep -aq 'RVCP-SUMMARY: TEST FAILED' "$rundir/sim.log"; then
    echo "$elf,FAIL,$cyc"
    grep -a 'RVCP' "$rundir/sim.log" | head -3 | sed "s/^/$elf: /" >&2
  elif [ "$rc" -ne 0 ]; then
    echo "$elf,FAIL(rc=$rc),$cyc"
  else
    echo "$elf,PASS,$cyc"
  fi
  rm -rf "$rundir"
done
